class Gs1ProductPage{static async render(params){console.log(params);const $page=$('#product');$('.gtin',$page).html(`<b>GTIN</b>: ${params.gtin}`);if(params.lot)
$('.lot',$page).html(`<b>Lot</b>: ${params.lot}`);if(params.serial)
$('.serial',$page).html(`<b>Serial</b>: ${params.serial}`);if(params.productionDate)
$('.productionDate',$page).html(`<b>Production date</b>: ${params.productionDate}`);if(params.expiryDate)
$('.expiryDate',$page).html(`<b>Expiry date</b>: ${params.expiryDate}`);if(params.softwareVersion)
$('.softwareVersion',$page).html(`<b>Software version</b>: ${params.softwareVersion}`);$('.description',$page).html($('<pre/>').text('TODO'));}}